svg.script:
// data → geometry (static layout; the script only animates it)
const V = [11, 12, 10.5, 12.5, 19, 22, 23.5, 25.5], N = V.length;
const bx = i => 156 + i * 74, by = v => 924 - v / 30 * 250, BW = 44;
const bars = document.getElementById('bars');
V.forEach((v, i) => {
  const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
  r.setAttribute('x', bx(i)); r.setAttribute('width', BW);
  r.setAttribute('fill', i < 4 ? '#e3ecd9' : '#1e2618');
  if (i < 4) { r.setAttribute('stroke', '#1e2618'); r.setAttribute('stroke-width', '1.5'); }
  bars.appendChild(r);
});
const pts = V.map((v, i) => [bx(i) + BW / 2, by(v) - 26]);
document.getElementById('line').setAttribute('d', pts.map((p, i) => (i ? 'L' : 'M') + p.join(',')).join(''));
const last = pts[N - 1];

// curves are algebra (GSAP names → functions)
const c = x => Math.min(1, Math.max(0, x));
const E = {
  expoOut: x => x >= 1 ? 1 : 1 - Math.pow(2, -10 * x),
  power4Out: x => 1 - Math.pow(1 - x, 5),
  power1Out: x => 1 - (1 - x) * (1 - x),
  power2InOut: x => x < .5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2,
  power2In: x => x * x * x,
  backOut: x => { const s = 1.7; return 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2); },
};
const tw = (t, start, dur, ease) => E[ease](c((t - start) / dur));
const $ = id => document.getElementById(id);

function frame(t) {
  // leave: everything goes together at the end of the loop (power2.in, 0.5 s)
  const out = 1 - tw(t, 6.5, 0.5, 'power2In');
  $('all').setAttribute('opacity', out);

  // eyebrow: already there at frame 0
  $('eyebrow').setAttribute('fill-opacity', 0.72 * tw(t, -0.2, 0.4, 'power1Out'));

  // words: one every 0.29 s, starting just before frame 0 so frame 0 is moving
  for (let k = 0; k < 5; k++) {
    const p = tw(t, -0.12 + k * 0.29 + (k > 1 ? 0.22 : 0), 0.3, 'power1Out');
    const w = $('w' + k);
    w.setAttribute('fill-opacity', p);
    w.setAttribute('dy', 0);
    w.parentNode.setAttribute('transform', '');
    w.style.transform = `translateY(${(1 - p) * 10}px)`;
    $('b' + k).firstElementChild.setAttribute('stdDeviation', (1 - p) * 5);
  }

  // card: appears in place (no travel), title bar wipes left→right
  const cp = tw(t, 1.75, 0.35, 'power1Out');
  $('card').setAttribute('opacity', cp);
  $('tbwipe').setAttribute('width', 888 * tw(t, 1.8, 0.45, 'power4Out'));

  // bars grow from their own baseline, 70 ms stagger, 720 ms expo.out
  [...bars.children].forEach((r, i) => {
    const p = tw(t, 2.15 + i * 0.07, 0.72, 'expoOut'), h = (924 - by(V[i])) * p;
    r.setAttribute('y', 924 - h); r.setAttribute('height', h);
  });

  // the line draws over them; the marker arrives under its own weight
  const lp = tw(t, 3.2, 0.9, 'power2InOut');
  $('line').setAttribute('stroke-dasharray', `${lp} 1`);
  const m = tw(t, 4.05, 0.42, 'backOut'), s = 16 * m;
  $('marker').setAttribute('x', last[0] - s / 2); $('marker').setAttribute('y', last[1] - s / 2);
  $('marker').setAttribute('width', Math.max(0, s)); $('marker').setAttribute('height', Math.max(0, s));

  // counter: steps at least 8 frames apart, so it reads as changing, not flickering
  const steps = [0, 4.2, 9.8, 15.1, 19.6, 22.4, 23.9];
  const k = Math.floor(c((t - 3.2) / (8 / 30 * steps.length)) * (steps.length - 1) + 1e-6);
  $('count').textContent = (t < 3.2 ? 0 : steps[Math.min(k, steps.length - 1)]).toFixed(1) + ' s';
  // 4.5 → 6.5 s: nothing moves. The payoff gets silence.
}

const q = /[?&]t=([\d.]+)/.exec(location.search);
const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
if (q) frame(parseFloat(q[1]));
else if (!reduce) { const t0 = performance.now(); const loop = n => { frame(((n - t0) / 1000) % 7); requestAnimationFrame(loop); }; requestAnimationFrame(loop); }
else frame(6.4);
